import java.util.List;

/**
 * Which insured item a damage entry of an incident names.
 *
 * <p>A damage entry names its item by type, the way the report is written;
 * what the clauses need is the insured item itself, with its enchantment and
 * its material. This is the one place that reads a report's item type against
 * the items a policy covers.
 *
 * <p>Changes whenever the MHPCO revises how a report is read against a policy
 * — notably once a policy may cover several items of the same type and each
 * entry must be matched to one of them. Knows nothing about what is
 * reimbursed for the item it finds.
 */
final class DamagedItem {

    private DamagedItem() {
    }

    /**
     * The insured item a damage entry names.
     */
    static Item of(List<Item> insured, Damage damage) {
        return insured.stream()
                .filter(item -> item.type().equals(damage.itemType()))
                .findFirst()
                .orElseThrow();
    }
}
